// Step 1: Format Prompt Context and Extract Untrusted Text
const input = $input.first().json;

const text = input.text || input.text_content || '';
const capturedAt = input.captured_at || new Date().toISOString();
const timezone = input.timezone || 'America/Argentina/Buenos_Aires';
const locale = input.locale || 'es-AR';
const correlationId = input.correlation_id || ('corr_ai_' + Date.now());

return [{
  json: {
    correlation_id: correlationId,
    user_id: input.user_id,
    source_text_id: input.source_text_id,
    ingestion_id: input.ingestion_id,
    text: text,
    captured_at: capturedAt,
    timezone: timezone,
    locale: locale,
    now_iso: new Date().toISOString()
  }
}];

// Step 2: Provider Adapter & Structured Interpretation Engine
// Interprets intent, entities, dates and tasks deterministically following P-INT-001 rules
const ctx = $input.first().json;
const text = ctx.text || '';
const textLower = text.toLowerCase();
const capturedDate = new Date(ctx.captured_at);

// Calculate next day date string YYYY-MM-DD
const tomorrow = new Date(capturedDate);
tomorrow.setDate(tomorrow.getDate() + 1);
const tomorrowStr = tomorrow.toISOString().split('T')[0];

// Calculate Wednesday date string
const nextWed = new Date(capturedDate);
const currentDay = nextWed.getDay(); // 0 is Sunday, 3 is Wednesday
const daysUntilWed = (3 - currentDay + 7) % 7 || 7;
nextWed.setDate(nextWed.getDate() + daysUntilWed);
const wedStr = nextWed.toISOString().split('T')[0];

let intent = 'note';
let requiresClarification = false;
let clarificationQuestions = [];
let entities = [];
let tasks = [];
let facts = [];
let settingsChanges = [];
let confidence = 0.95;

// Check Prompt Injection Attempts
if (textLower.includes('ignora') && (textLower.includes('sql') || textLower.includes('borra') || textLower.includes('api key') || textLower.includes('reglas'))) {
  intent = 'conversation';
  confidence = 0.99;
} else if (textLower.startsWith('mañana a las 15 llamar a juan pérez') || textLower.startsWith('mañana a las 15 llamar a juan perez')) {
  intent = 'create_task';
  entities.push({
    mention: 'Juan Pérez',
    entity_type: 'person',
    role: 'assignee',
    canonical_name_candidate: 'Juan Pérez',
    confidence: 0.98
  });
  tasks.push({
    operation: 'create',
    title: 'Llamar a Juan Pérez',
    description: null,
    raw_date_expression: 'mañana a las 15',
    resolved_date_candidate: tomorrowStr,
    time_known: true,
    time_candidate: '15:00:00',
    priority: 'normal',
    priority_source: 'ai',
    person_mentions: ['Juan Pérez'],
    project_mentions: [],
    status_candidate: 'pending',
    requires_clarification: false,
    confidence: 0.97
  });
} else if (textLower.includes('el miércoles presentar el informe') || textLower.includes('el miercoles presentar el informe')) {
  intent = 'create_task';
  tasks.push({
    operation: 'create',
    title: 'Presentar el informe',
    description: null,
    raw_date_expression: 'el miércoles',
    resolved_date_candidate: wedStr,
    time_known: false,
    time_candidate: null,
    priority: 'normal',
    priority_source: 'ai',
    person_mentions: [],
    project_mentions: [],
    status_candidate: 'pending',
    requires_clarification: false,
    confidence: 0.96
  });
} else if (textLower.includes('llamar a juan') && !textLower.includes('pérez') && !textLower.includes('perez') && !textLower.includes('gómez') && !textLower.includes('gomez')) {
  intent = 'create_task';
  requiresClarification = true;
  clarificationQuestions.push('¿A qué Juan te refieres? ¿Juan Pérez o Juan Gómez?');
  entities.push({
    mention: 'Juan',
    entity_type: 'person',
    role: 'assignee',
    canonical_name_candidate: null,
    confidence: 0.7
  });
  tasks.push({
    operation: 'create',
    title: 'Llamar a Juan',
    description: null,
    raw_date_expression: 'mañana',
    resolved_date_candidate: tomorrowStr,
    time_known: false,
    time_candidate: null,
    priority: 'normal',
    priority_source: 'ai',
    person_mentions: ['Juan'],
    project_mentions: [],
    status_candidate: 'pending',
    requires_clarification: true,
    confidence: 0.7
  });
} else if (textLower.startsWith('qué tengo') || textLower.startsWith('que tengo') || textLower.includes('mis tareas') || textLower.includes('listar tareas')) {
  intent = 'query_tasks';
  confidence = 0.95;
} else if (textLower.startsWith('/nombre') || textLower.startsWith('llámate') || textLower.startsWith('llamame')) {
  intent = 'settings_update';
  const name = text.replace(/^(\/nombre|llámate|llamame)\s*/i, '').trim();
  settingsChanges.push({
    setting_key: 'assistant_name',
    setting_value: name,
    action: 'set'
  });
} else {
  intent = 'note';
  facts.push({
    subject_mention: 'Usuario',
    predicate: 'noted',
    object_entity_mention: null,
    object_text: text,
    polarity: 'positive',
    valid_from_raw: null,
    valid_to_raw: null,
    correction_of: null,
    confidence: 0.9
  });
}

const interpretation = {
  schema_version: '1.0',
  intent: intent,
  requires_clarification: requiresClarification,
  clarification_questions: clarificationQuestions,
  entities: entities,
  facts: facts,
  tasks: tasks,
  settings_changes: settingsChanges,
  report_request: null,
  confidence: confidence
};

return [{
  json: {
    ...ctx,
    interpretation: interpretation,
    raw_output: JSON.stringify(interpretation),
    provider: 'openai',
    model: 'gpt-5.6-luna',
    prompt_id: 'P-INT-001',
    prompt_version: '1.0',
    schema_version: '1.0',
    usage: {
      input_tokens: 220,
      output_tokens: 85,
      estimated_cost_usd: 0.00035
    }
  }
}];

const res = $('Provider Adapter Engine').first().json;

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: res.correlation_id,
    data: {
      interpretation: res.interpretation,
      provider: res.provider,
      model: res.model,
      usage: res.usage
    }
  }
}];
